import EventCard from "./EventCard";

function Calendar({ events }) {

    const dates = [
        "Monday",
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday",
        "Saturday",
        "Sunday"
    ];

    return (

        <div className="calendar">

            {dates.map((date) => (

                <div
                    key={date}
                    className="day-column"
                >

                    <h3>{date}</h3>

                    {events
                        .filter(
                            (event) =>
                                event.date === date
                        )
                        .map((event) => (

                            <EventCard
                                key={event.id}
                                event={event}
                            />

                        ))
                    }

                </div>

            ))}

        </div>

    );

}

export default Calendar;
